INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(137700, 0, 1377, 0, 0, 0, 'Silithus', 'Silithus is a wasteland of sand, wind and stone in the far southwest of Kalimdor, reached on foot only by the northwestern ridge out of Un''Goro Crater. Nearly a thousand years ago the qiraji poured out of their fortress city of Ahn''Qiraj and swept across this desert in the War of the Shifting Sands. The night elves under Fandral Staghelm fought them here and lost Southwind Village, until at last the insects were sealed behind the Scarab Wall in the south. Today the silithid hives of Ashi, Zora and Regal swarm across the sands once more. The Cenarion Circle keeps watch over the wastes from Cenarion Hold at the heart of the desert and from the graves of Valor''s Rest in the north. Other powers stir as well. Twilight''s Hammer cultists camp across the desert, and dwarven explorers keep a camp in the southern hills.', 'warcraft.wiki.gg/wiki/Silithus (only land route through northwestern Un''Goro; Cenarion Hold; silithyst world PvP); quest 1124 description (west of Un''Goro via the northwestern ridge); quests 8275, 8276, 8507, 8731 (Horde and Alliance volunteers); DB: gameobject 49390-49392 state 0, no game_event_gameobject rows; creature 15499, 15500 permanent; quest 1124 description (an ancient war between the night elves and a malign alien power, sealed); aq_gate_quest.sql (module gate 176146-176148 seen before state 5); warcraft.wiki.gg/wiki/War_of_the_Shifting_Sands (Scarab Wall sealing)'),
(137701, 1, 1377, 1, 0, 0, 'Valor''s Rest', 'In the far northeast of Silithus, close to the ridge that climbs out of Un''Goro Crater, lies Valor''s Rest, a graveyard the Cenarion Circle calls the final resting place of those who fell in these wastes. A few of the Circle''s agents keep a quiet camp beside the graves. Their leader, Layo Starstrike, receives those sent by Rabine Saturna of Nighthaven, and he warns every visitor that the past lives on in this desert and must be handled carefully, lest it wake. The tauren Jarund Stoutstrider shares his watch, and Zannok Hidepiercer sells leatherworking supplies to travelers passing through.', 'quest 1124 description and reward text (final resting spot for the fallen of the wastes); npc_text 6155 (Layo: the past lives in these wastes, we must be careful not to awaken it); warcraft.wiki.gg/wiki/Valor''s_Rest (camp in northern Silithus, Layo the leader, Jarund a tauren, Zannok); zone_areas 3077: Layo 13220, Jarund 11805, Zannok 12956, spirit healer'),
(137702, 1, 1377, 2, 0, 0, 'Staghelm Point', 'On a high peak in northeastern Silithus stands Staghelm Point, an old night elven tower looking out over the desert. Its lone keeper is Ralo''shan the Eternal Watcher, a night elf who says it was here, nearly a thousand years ago, that the qiraji began their march of destruction across Kalimdor. She has been slain a hundred times and always wakes again at her post. Some call her cursed, others a herald of a new age, and she herself warns that ancient forces stir and that nightmares now come out of the Dream. A bronze drake of the Brood of Nozdormu circles in the sky nearby, and cultists of the Twilight''s Hammer camp close by.', 'warcraft.wiki.gg/wiki/Staghelm_Point (night elven tower on a peak in northeastern Silithus, Ralo''shan, bronze drake circling); npc_text 7801-7804 (Ralo''shan); creature 15185 Brood of Nozdormu spawn at -6678,33 z162 near the tower; zone_areas 3426: Twilight Overlord, Master, Flamereaver, Avenger; CreatureDisplayInfo 15308 (night elf female)'),
(137703, 1, 1377, 3, 0, 0, 'Twilight''s Run', 'Twilight''s Run is a cave tucked into the northeast corner of Silithus, one of the Twilight''s Hammer''s bases of operation in the desert. Outside its mouth the cult keeps a camp of overlords, masters and flamereavers, and within the tunnels dwells Vyral the Vile, the local leader of the cult in Silithus, who carries a signet ring. The druids of Cenarion Hold count the horrors of the cave as formidable indeed, and Huum Wildmane names Vyral among the heads of the serpent that the Circle means to strike.', 'quest 8321 description and reward text; warcraft.wiki.gg/wiki/Staghelm_Point (Twilight''s Run down the road, small camp outside its entrance); creature 15202 Vyral at -6320,16; Twilight Flamereaver 15201 nearby; WMOAreaTable: 3446 is the indoor area of WMO 2938 (cave); vmaps 001_31_43.vmtile spawn 165997 and Md_Mountaincave_Medium_H.wmo.vmo (root 2938, group 15847); quest 8320 description (heads of these serpents)'),
(137704, 1, 1377, 4, 0, 0, 'Hive''Ashi', 'North of Cenarion Hold the sand rises into the mounds of Hive''Ashi, the northern of the three great silithid hives of Silithus. Swarmers, stingers, defenders and sandstalkers boil across its slopes while workers labor below, and the truesilver veins there come coated in ooze. A rare and dangerous silithid called Rex Ashil is sometimes seen among them. Inside, as in each of its sister hives, stands a crystal carved with qiraji glyphs, and the dwarves of the Bronzebeard camp suspect these crystals are tied to the swarms now pouring from the hives. A Cenarion scout, Jalia, lies hidden nearby to watch, certain that greater, darker powers drive the insects.', 'zone_areas 2742: Hive''Ashi Swarmer, Defender, Sandstalker, Worker, Stinger, Rex Ashil 14475 (rank 2), Cenarion Scout Jalia 15611, Hive''Ashi Glyphed Crystal 180454, Ooze Covered Truesilver; quest 8309 description (glyphs on the crystals, increased activity); npc_text 8065 (Jalia)'),
(137705, 1, 1377, 5, 0, 0, 'Cenarion Hold', 'Cenarion Hold is the fortress of the Cenarion Circle at the heart of Silithus, raised where an old night elven settlement stood, to guard against what lies sealed in the south. The infantry of the hold deal harshly with anyone who spills blood on neutral ground, Captain Vish Kozus keeps watch from the top of the watchtower, and flight masters link the hold to the rest of Kalimdor. At the inn, Calandrath misses the birds and trees of Auberdine and wonders how anyone makes the bitter sandworm meat of the desert fit to eat. A bronze drake circles overhead.', 'warcraft.wiki.gg/wiki/Cenarion_Hold (Circle took over the ancient night elven settlement, set up after the war to guard C''Thun; leaders Mar''alith and Vish Kozus); creature_text 15184 (You dare spill blood on neutral ground?); quest 8283 description (Vish Kozus at the top of the watchtower); quest 8280 description; npc_text 7731 (Baristolth''s promise); zone_areas 3425: Cloud Skydancer 15177, Runk Windtamer 15178, Brood of Nozdormu 15185; quest 8307 description (misses Auberdine; bitter sandworm meat)'),
(137706, 1, 1377, 6, 0, 0, 'Twilight Base Camp and Twilight Post', 'West of Cenarion Hold the Twilight''s Hammer has pitched two of its camps, Twilight Base Camp and, farther west, Twilight Post. Geolords, avengers and stonecallers of the cult crowd their tents and perform rituals day and night, and the druids suspect those rituals are linked to the pulsing red crystals scattered across the desert. In each camp stand wind stones, lesser, common and greater, through which the cultists summon powerful elemental nobles and take their orders. Twilight Keepers such as Havunth and Mayna guard chapters of the cult''s secret lexicon, and prophets travel between the camps under heavy escort. The cult''s cooks hunt sandworms for food, though how they make the bitter meat palatable is anyone''s guess.', 'quest 8320 description (camps, rituals day and night, pulsing red crystals); quest 8331 description (wind stones among the camps); quest 8279 description (Twilight Keepers hold the Lexicon chapters); zone_areas 2739 and 3098: Geolord, Avenger, Stonecaller, Havunth 11804, Prophet 15308, Mayna 15200, wind stones 180529-180564, Sandy Cookbook 180503; creature_loot_template: Havunth drops Lexicon Chapter 3; quest 8361 description (elemental nobles, orders); quest 8307 description (sandworm meat bitter); mod-individual-progression zone_silithus.sql (prophets 15308 with avenger escorts, phase 1)'),
(137707, 1, 1377, 7, 0, 0, 'The Crystal Vale', 'In the far northwest corner of Silithus lies the Crystal Vale, a valley rich in thorium and ruled by elementals of earth and air. Desert rumblers lumber across its floor, dust stormers whirl across it, and a fierce elemental named Huricanian is said to roam there. Duke Hydraxis of the Waterlords counts the vale''s stormers and rumblers among the foes he would see destroyed. Within the vale lie the remains of the Ravaged Twilight Camp. The cult once thrived there, but now scattered wood, canvas and fragments of clay tablet are all that mark the spot. A lone human, Highlord Demitrian, keeps vigil over the ruin and bids visitors look upon it and know the power the elements hold.', 'warcraft.wiki.gg/wiki/Crystal_Vale (far northwestern corner, earth and air elementals, thorium, Ravaged Twilight Camp, Demitrian); zone_areas 2740 and 3100: Desert Rumbler, Dust Stormer, Huricanian 14478 (rank 4), Twilight Tablet Fragment; quest 8284 description (camp once thrived, elementals, wood and canvas); quest 6805 (Azshara, Hydraxis: Stormers and Rumblers); npc_text 6812 (Demitrian)'),
(137708, 1, 1377, 8, 0, 0, 'Southwind Village', 'In eastern Silithus lie the ruins of Southwind Village, once the night elves'' base of operations in this land. It fell in the War of the Shifting Sands and was overrun by the silithid, who have held it ever since. The tortured spirits of fallen druids and sentinels still wander the broken streets, led by the Shade of Ambermoon, and their death wails rouse the hive that has claimed the village tower, around which a mass of wasps endlessly circles. The druids of Nighthaven believe a Reliquary of Purity was left here long ago.', 'quest 1125 description and reward text; quest 1126 description (tower with the mass of wasps); creature_text 12178/12179 (death wail stirs the hive); warcraft.wiki.gg/wiki/Southwind_Village (spirits led by the Shade of Ambermoon); npc_text 7783 (Aendel: the ghostly figure looks at you with mistrust); quest 5527 description (Reliquary of Purity at Southwind); warcraft.wiki.gg/wiki/War_of_the_Shifting_Sands (Southwind fell)'),
(137709, 1, 1377, 9, 0, 0, 'Bones of Grakkarond', 'South of Cenarion Hold lie the Bones of Grakkarond, the remains of a great dragon stretched across the open desert. Dredge crushers and stonelash scorpids prowl among them, cyclone warriors whirl past, and desert rumblers lumber through the sand. Who the dragon was in life, and how it came to die here, the desert does not say. To most who pass it seems a forgotten place, one more field of bones in a land that has seen too many.', 'quest 8315 description (glyphs, Bones of Grakkarond south of Cenarion Hold, bones of a large dragon); zone_areas 3257: Dredge Crusher, Stonelash Pincer, Cyclone Warrior, Desert Rumbler; warcraft.wiki.gg/wiki/Bones_of_Grakkarond (bones of a huge dragon); warcraft.wiki.gg/wiki/Bones_of_Grakkarond'),
(137710, 1, 1377, 10, 0, 0, 'Hive''Zora', 'Hive''Zora sprawls across western Silithus, its mounds crawling with wasps. Hive sisters, reavers, waywatchers and tunnelers guard the hive, and a rare silithid called Zora lurks within. Deep in a tunnel full of the insects hides Cenarion Scout Azenel, who would much rather be elsewhere but means to watch the silithid day in and day out for as long as it takes to help win the war. Silithyst geysers break through the dunes around the hive.', 'zone_areas 2743: Hive''Zora Wasp x85, Hive Sister, Reaver, Waywatcher, Tunneler, Zora 14474, Scout Azenel 15610, Ironforge Brigade 15440-15444, Carnes 15903, Marshal Bluewall 17080, Silithyst Geyser; npc_text 7874 (Janela); npc_text 8064 (Azenel); npc_text 8212 (Carnes); quest 8507 description; quest 9419 description'),
(137711, 1, 1377, 11, 0, 0, 'Hive''Regal', 'Hive''Regal is the southern hive of Silithus, the haunt of slavemakers, spitfires, ambushers, burrowers and hive lords, with a rare beast called Lapress among them. Stonelash flayers and rock stalkers hunt the sands around its mounds. Like its sister hives it guards a crystal carved with qiraji glyphs. Deep in its tunnels Cenarion Scout Landion creeps close enough to the insects to go unnoticed, though he would not advise anyone to try it.', 'zone_areas 2744: Hive''Regal Slavemaker, Spitfire, Hive Lord, Ambusher, Burrower, Lapress 14473, Krug Skullsplit 15612, Merok, Kirika''s camp 17079; warcraft.wiki.gg/wiki/Hive''Regal (southern Silithus, Natalia, Landion); npc_text 8059 (Krug); quest 8731 reward text (signed in silithid blood); quest 9422 description; npc_text 8063 (Landion); quest 8306 objectives; zone_areas 2744: Stonelash Flayer, Rock Stalker; gameobject 180453 Hive''Regal Glyphed Crystal'),
(137712, 1, 1377, 12, 0, 0, 'Bronzebeard Encampment', 'In the southern hills of Silithus, east of the Scarab Wall, the dwarves of Brann Bronzebeard''s expedition have made camp. They came to search the hives for lost artifacts, and between the four of them, monkey included, they speak thirty-eight languages, Titan among them. Brann himself has gone missing again. Rutgar Glyphshaper and Frankal Stonebridge stay on with Brann''s monkey Glibb, sure they are onto something huge, though their pleas to Ironforge for an army go unanswered. In the mountains behind the camp hunts Deathclasp, a giant scorpid.', 'warcraft.wiki.gg/wiki/Bronzebeard_Encampment (southern Silithus, east of the Scarab Wall); npc_text 7755, 7764, 7761 (artifacts, 38 languages, requests to Ironforge); npc_text 7736 (Bronzebeard''s gone missing again); quests 8282, 8283 (Deathclasp in the southern mountain range behind Bronzebeard''s camp); creature 15172 Glibb <Brann Bronzebeard''s Pet Monkey>; npc_text 7761 (onto something huge)'),
(137713, 1, 1377, 13, 0, 0, 'Twilight Outpost', 'Far in the southwest of Silithus, not far from the Scarab Wall, stands Twilight Outpost, the southernmost of the Twilight''s Hammer camps. Geolords, avengers and stonecallers fill it, with Twilight Masters among them, and a prophet passes through under heavy escort. Twilight Keeper Exeter guards a chapter of the cult''s lexicon nearby. Wind stones of every size, lesser, common and greater, stand among the tents for the cult to call on the elemental powers it serves, and at times a Twilight Lord named Everun is seen walking the camp.', 'zone_areas 3099: Stonecaller, Avenger, Geolord, Twilight Master 11883, Twilight Lord Everun 14479 (rank 4), Twilight Prophet 15308, wind stones 180456, 180461, 180466, 180518; creature 11803 Exeter at -7964,1977 (1377 grid, beside the outpost); loot: Lexicon Chapter 2; quest 8361 description (elemental nobles summoned by rituals)'),
(137714, 1, 1377, 14, 0, 0, 'The Scarab Wall', 'In the far southwest of Silithus runs the Scarab Wall, raised at the end of the War of the Shifting Sands to seal the qiraji and their silithid within Ahn''Qiraj. For a thousand years it has stood. Near this sacred barrier lies a single crystalline tear, left as a symbol of the great losses of that war. Scorpids creep along the foot of the wall, and a rare creature called Setis is known to prowl there.', 'warcraft.wiki.gg/wiki/Scarab_Wall (molded from the sand, bronze dragonflight barrier many times taller); quest 8305 description and reward text (crystalline tear near the sacred barrier); zone_areas 2737: Crystalline Tear 180633, Setis 14471, Stonelash Flayer'),
(137715, 1, 1377, 15, 0, 0, 'Gates of Ahn''Qiraj', 'In the Scarab Wall stand the Gates of Ahn''Qiraj, the great doors of the qiraji fortress city. When the War of the Shifting Sands ended they were sealed with the insects behind them, and for a thousand years nothing passed through. Before them rises the Scarab Dais, a broad stone platform at the foot of the wall. Beyond the gates lie the ruins of the outer city and, deeper within, the temple of the qiraji.', 'quest 8743 request text (the Scarab Gong, slackened maw); warcraft.wiki.gg/wiki/Gates_of_Ahn''Qiraj (gates stayed open, Ruins and Temple beyond); DB: gate doors 180904/180898/180899 spawn state 0 (open); posarea: 3478 at -8200,1530 west of the door, 2741 at the gong'),
(137716, 2, 1377, 1, 0, 0, 'Commander Mar''alith', 'Commander Mar''alith leads the Cenarion Circle''s forces at Cenarion Hold, a night elf warrior bound by duty to his outpost even while his heart is elsewhere. His beloved Natalia has gone missing after weeks of strange behavior, talking to herself when she thought no one was near and insisting that her research must go on, and the captain of his guard admits he has not been himself since. Those who come to him find him distracted, asking why this has come now, with so much work still to be done. Still the war is his to run, and he rewards well those who bring him word of the Twilight''s Hammer.', 'npc_text 7732; quest 8304 description and reward text; npc_text 7733 (Vish Kozus: the Commander has not been himself); warcraft.wiki.gg/wiki/Commander_Mar''alith (night elf warrior, head of the Circle''s forces); quests 8287, 8498 (intelligence on the cult turned in to him)'),
(137717, 2, 1377, 2, 0, 0, 'Baristolth of the Shifting Sands', 'Baristolth of the Shifting Sands is a night elf who lingers among the tents of Cenarion Hold with his eyes on the desert. A thousand years ago, he says, death had all but claimed him when a great one of the bronze dragonflight breathed once upon his broken body and let the sands of time heal his wounds, then bound him to remain a Watcher for as long as he must. Now the land shudders, the hive stirs and the drakes of the Brood of Nozdormu have returned to the skies, and Baristolth knows a second war is upon them. The time has come to keep a promise he made in that long-ago war.', 'quest 8286 description and reward text; npc_text 7731; creature_text 15180 (the Brood of Nozdormu have returned); warcraft.wiki.gg/wiki/Baristolth_of_the_Shifting_Sands (night elf, Watcher of the bronze dragonflight)'),
(137718, 2, 1377, 3, 0, 0, 'Geologist Larksbane', 'Geologist Larksbane is a dwarf scholar serving the Cenarion Circle at Cenarion Hold, and she hears what others miss: a humming from the crystals of the desert that grows louder every day, which she believes is driving the silithid mad. Her work turns on the hidden writings of Silithus. She gathers the clay tablets left in a ruined Twilight''s Hammer camp in the northwest to learn what the cult is doing here, and she studies the glyphed crystals that the qiraji have set within the hives.', 'npc_text 7734; warcraft.wiki.gg/wiki/Geologist_Larksbane (female dwarf, Cenarion Circle); quest 8284 description; quest 8314 description'),
(137719, 2, 1377, 4, 0, 0, 'Huum and Bor Wildmane', 'The tauren brothers Huum and Bor Wildmane are druids of the Cenarion Circle at Cenarion Hold who keep watch on an enemy most others overlook. While every eye is on the silithid, they track the Twilight''s Hammer. Huum, the elder, hears the spirits of Silithus weeping for the woeful tale the land has to tell, and he directs the strikes against the cult''s geolords and its local leader. Bor is blunter. He gathers up the cult''s coded papers just to keep them out of circulation, and he wants the elemental templars the cultists summon given a proper beating, since nothing throws troops into disarray like taking out the chain of command.', 'npc_text 7797 (Bor: my big brother and I keep an eye on the Twilight''s Hammer crazies); npc_text 7779 (Huum: the land weeps); quests 8320, 8321 (Huum); warcraft.wiki.gg/wiki/Huum_Wildmane and Bor_Wildmane (tauren druids, brothers); quests 8318, 8361 descriptions (Bor)'),
(137720, 2, 1377, 5, 0, 0, 'Hermit Ortell', 'Hermit Ortell is a human who, rumor has it, once belonged to the Twilight''s Hammer and deserted his sect. He hides in a cave in the mountains south of Southwind Village and lives there as a hermit, wanting nothing to do with strangers, and he sends off anyone who comes calling. Those who do find him are met with suspicion and a string of questions: how did they find him, who are they, and were they followed?', 'quest 8285 description and request text; quest 8279 description; quest 8323 description; npc_text 7816; warcraft.wiki.gg/wiki/Hermit_Ortell (human, deserter, Ortell''s Hideout)'),
(137721, 2, 1377, 6, 0, 0, 'Highlord Demitrian', 'Highlord Demitrian, a human, keeps a strange vigil in the ruined Twilight''s Hammer camp of the Crystal Vale, bidding visitors look upon the ravaged field and behold the might of the elements. He speaks of the Old Gods as the makers of the world, cast down by the Titans, and the lord he serves is Thunderaan, Prince of Air. In the Elemental Sundering, he says, Ragnaros''s lieutenants Geddon and Garr betrayed Thunderaan, and the Firelord struck him down with Sulfuras and fed on his essence. What remained was sealed in a talisman of binding, broken in two and given to those lieutenants. Demitrian holds the vessel of his master''s rebirth and wants elementium and the Firelord''s essence to free him.', 'npc_text 6812, 6843, 6844, 6867-6870, 6954-6958; quests 7785, 7786 reward text, 7787 description (lying wretch, his betrayal); warcraft.wiki.gg/wiki/Highlord_Demitrian (human, Ravaged Twilight Camp, Crystal Vale)'),
(137722, 2, 1377, 7, 0, 0, 'Windcaller Proudhorn', 'Windcaller Proudhorn, a tauren of the Cenarion Circle, welcomes the volunteers who answer the call raised by the Circle''s emissaries in Orgrimmar and Ironforge. The silithid, those emissaries warn, have been left unchecked too long and are preparing to spread, and tremors near hives all across Azeroth betray their swelling numbers. Proudhorn is sure that while Cenarion Hold stands, victory over the silithid is certain, provided the supplies keep coming. To her mind the desert worms threaten the caravans more than the insects do: dredge strikers recently ravaged a whole shipment of morrowgrain, and their larger southern cousins wait to move in.', 'quests 8275, 8276 description and reward text; creature 15187 Jademoon in Ironforge, 15188 Blackhoof in Orgrimmar; quests 8280, 8281; npc_text 7746; warcraft.wiki.gg/wiki/Windcaller_Proudhorn (female tauren)'),
(137723, 3, 1377, 1, 0, 0, 'The Twilight Mystery', 'Geologist Larksbane of Cenarion Hold wants to know what the Twilight''s Hammer is doing in Silithus. A camp of the cult once thrived northwest of the hold, but anyone who goes there now finds the ground swarming with elementals and only scattered wood and canvas to mark where the tents stood. From the site she has recovered a few fragments of a clay tablet, too few to piece together anything useful, and she needs someone to brave the elementals and gather the rest so the tablet can be restored and read.', 'quest 8284 description'),
(137724, 3, 1377, 2, 0, 0, 'Dearest Natalia', 'Commander Mar''alith''s beloved Natalia has vanished. For weeks before, she had been acting strangely, talking to herself when no one was around and insisting that all was well and that her research must be allowed to go on. She was last seen heading for the dwarven camp of Bronzebeard''s expedition in the south. The commander''s soldiers are spread too thin to search, and duty binds him to his post, so he asks for help: go to the dwarves and question them about what became of her.', 'quest 8304 description'),
(137725, 3, 1377, 3, 0, 0, 'The Prophecy of C''Thun', 'Since Natalia Mar''alith''s madness the three hives of Silithus have been spewing out bugs, and the dwarves of the Bronzebeard camp want to know why. Rutgar Glyphshaper suspects the glyphs covering the strange crystals inside the hives, and he wants rubbings taken from the crystals of Hive''Ashi, Hive''Zora and Hive''Regal so the dwarves can make sense of the madness. Frankal Stonebridge has his own plan: an elixir to help read the tongue of the silithid and the qiraji, for which he needs a brain from the silithid of each hive.', 'quests 8309, 8310 descriptions'),
(137726, 3, 1377, 4, 0, 0, 'The Abyssal Council', 'The Twilight''s Hammer has set up camps across Silithus and performs rituals in them day and night. The druids of Cenarion Hold do not yet know its plans, though they suspect a link with the pulsing red crystals spread across the desert, and Huum Wildmane means to strike first at the heads of the serpent, the Twilight geolords, and then at the cult''s local leader. His brother Bor has watched cultists call up mighty elemental nobles and receive orders from them. Whether these are the beings the cult worships or messengers of something greater, none can say.', 'warcraft.wiki.gg/wiki/Abyssal_Council (templars, dukes, lords); quests 8320, 8361 descriptions'),
(137727, 3, 1377, 5, 0, 0, 'The Spirits of Southwind', 'Layo Starstrike of Valor''s Rest believes the Cenarion Circle''s work in Silithus should begin at the ruins of Southwind Village to the southwest, once a night elf base of operations and long since overrun by the hives. He was not alive for the great tribulations of the old war, but he hopes the Circle can bring an end to a threat that was supposed to have died generations ago. First, the tortured spirits of druids and sentinels who wander the ruins must be freed, for no being, Alliance or Horde, deserves to be trapped as a tortured spirit.', 'quest 1125 description and request text; quest 1124 reward text'),
(137728, 3, 1377, 6, 0, 0, 'The Scepter of the Shifting Sands', 'Baristolth of the Shifting Sands has waited a thousand years for a sign, and now the hive stirs once more around Cenarion Hold. In the old war, he says, the bronze flight bound him to remain as a Watcher, and he made a promise then that he means to keep. Before he can act he must be sure of one thing. War has come again, he believes, and so he asks a seeker to venture to the Caverns of Time in Tanaris and learn whether his master of the bronze has returned.', 'quest 8286 description and reward text; npc_text 7731');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(137700, 1, 3, 255, 'Now the Circle is calling for help. Its envoys in the Horde and Alliance capitals warn that the silithid, too long left unchecked, are readying to spread, and volunteers of both factions pour into Cenarion Hold to take the fight to the hives.', 'quests 8275, 8276 descriptions; mod-individual-progression ipp_aware_npcs.sql: npc_ipp_preaq (15176, 15180, 15181, 15183, 15191, 15194, 15293, 15306, 15612 and others, seen from state 3); ipp_aware_npcs.sql: emissaries 15187, 15188 npc_ipp_preaq'),
(137700, 2, 4, 4, 'The Scarab Gong has sounded, and when the gates of Ahn''Qiraj swung open the qiraji poured out upon the desert. The land itself has broken: great resonating crystals of the qiraji have burst through the earth, guarded by supreme anubisath warbringers and a qiraji lieutenant general, and colossi of obsidian stone have risen at the three hives.', 'mod-individual-progression aq_war.sql: colossi, Nokhor, supreme warbringers and resonating crystals in IPPPHASE (state 4 only in 1377, 2737, 2741 and the hives); aq_war.sql creature_text 15693 (gong emotes: crystals break through the crust, colossi rise)'),
(137700, 3, 5, 255, 'The gates of Ahn''Qiraj stand open and the war has been carried inside, where the fighting goes on day and night. Cenarion Hold now sends its volunteers on field duty to the posts outside the hives, and across the dunes Horde and Alliance race each other for silithyst, the crystal treasure drawn from geysers in the sand.', 'npc_text 8214, 8216 (gates open, fighting inside day and night); quests 8507, 8731 (field duty); quests 9415, 9416, 9419, 9422 (silithyst); mod-individual-progression ipp_aware_npcs.sql: npc_ipp_aq (15498, 15499, 15500, 15540, 16091, seen from state 5); mod-individual-progression ipp_aware_npcs.sql: Orgrimmar Legion and Ironforge Brigade posts phaseMask IPPPHASE_II (IndividualProgression.cpp checkIPPhasing: Silithus and the hives from state 5); zone_silithus.sql: 9415, 9416 need quest 66005 (state 5)'),
(137704, 1, 4, 4, 'Since the gong was rung, the Colossus of Ashi has broken free of its cocoon beneath the hive, a towering creature of obsidian stone that now stands among the swarm, and researchers at Cenarion Hold covet a fresh sample of its husk.', 'mod-individual-progression aq_war.sql: colossi, Nokhor, supreme warbringers and resonating crystals in IPPPHASE (state 4 only in 1377, 2737, 2741 and the hives); aq_war.sql creature_text 15693 group 3 (breaks free of its cocoon beneath Hive''Ashi); posarea: Colossus of Ashi -6545,967 in 2742; quest 8857 description (husk sample)'),
(137705, 1, 3, 255, 'The hold has filled for war. Druids and volunteers of the Horde and Alliance alike gather under Commander Mar''alith, Windcaller Proudhorn frets over the supply caravans, a dwarven geologist listens to the humming of the desert crystals, and Baristolth waits among the tents on a promise a thousand years old.', 'mod-individual-progression ipp_aware_npcs.sql: npc_ipp_preaq (15176, 15180, 15181, 15183, 15191, 15194, 15293, 15306, 15612 and others, seen from state 3); quest 8280 description; npc_text 7731, 7734'),
(137705, 2, 4, 4, 'For now three colossus researchers camp in the hold as well, eager to rush fresh husk samples from the great colossi of the hives to buyers in Booty Bay and at Light''s Hope Chapel before the samples spoil.', 'aq_war.sql: Colossus Researchers Sophia, Nestor, Eazel (15797-15799) npc_ipp_aqwar, state 4 only, posarea 3425; quests 8857, 8859 descriptions'),
(137705, 3, 5, 255, 'With the gates open, the hold settles in for a long war. Windcaller Kaldon assigns field duty to new volunteers, Warden Haro and others who came to aid their fellow druids have chosen to stay, and Keyl Swiftclaw insists the war has only just begun, with brave fighters battling inside Ahn''Qiraj day and night.', 'mod-individual-progression ipp_aware_npcs.sql: npc_ipp_aq (15498, 15499, 15500, 15540, 16091, seen from state 5); quests 8507, 8731 (Kaldon); npc_text 8214 (Haro), 8216 (Keyl)'),
(137706, 1, 0, 255, 'The druids have since learned whose voice answers at these stones. Behind the cult stands a darker master, the Abyssal Council, and the wind stones of camps like these are the very means by which it rules the Twilight''s Hammer.', 'quest 8331 description (Abyssal Council controls the Hammer through the wind stones)'),
(137706, 2, 0, 255, 'Calandrath''s question has an answer. A sandy cookbook left in the camp holds a recipe for sandworm meat, and the smoked desert dumplings made from it turned out far better than anyone expected from the Twilight''s Hammer.', 'quest 8307 reward text (recipe in the book); quest 8317 reward text (did not expect such good taste from the Twilight''s Hammer)'),
(137707, 1, 0, 255, 'The clay tablet gathered from the ruined camp, once decoded, read as a cultist''s diary. Pilgrims had come from many places to build a wind stone and speak with their masters, and this northern group, scorning the doubts of the others, finished first and readied the rituals to summon Baron Kazum himself, sure he would be pleased. There the diary ends.', 'item 20405 Decoded Tablet Transcription (page_text 2807-2809), StartItem of 8287, handed over when 8287 is accepted (8279 RewardNextQuest 8287)'),
(137708, 1, 3, 255, 'A wary ghost, Aendel Windspear, now lingers among the ruins as well. She watches the living with mistrust in her eyes and says nothing at all to those who come near her.', 'npc_text 7783; ipp_aware_npcs.sql: 15293 npc_ipp_preaq (state 3)'),
(137708, 2, 0, 255, 'Southwind''s fall has a name the night elves still mourn. During the war Fandral Staghelm ordered his son Valstann to defend the village, a decision he would come to regret, for Valstann lost his life there on the day Southwind fell to the armies of Ahn''Qiraj.', 'item 20415 The War of the Shifting Sands (8303 StartItem), page_text 2795-2796'),
(137709, 1, 0, 255, 'It matters to the qiraji after all. A hive crystal''s glyphs picture their emissary meeting three silithid at a great dragon''s bones, and Geologist Larksbane is sure these are the bones in question. A code of calling traced in the sand here, she reasons, would bring the overlords first and then the emissary, each believing fresh messages wait to be carried.', 'quest 8315 description'),
(137709, 2, 0, 255, 'She was right. Her glyphs, traced in the sand among the bones, called down the silithid overlords and at last the emissary itself, and when it fell, the means to unlock the crystal''s hidden messages was taken from its body.', 'quest 8315 log description and reward text'),
(137710, 1, 4, 4, 'The Colossus of Zora has risen, a creature of obsidian stone so vast that its shadow falls across the whole of Silithus, and it now towers over the hive among the swarming wasps.', 'mod-individual-progression aq_war.sql: colossi, Nokhor, supreme warbringers and resonating crystals in IPPPHASE (state 4 only in 1377, 2737, 2741 and the hives); aq_war.sql creature_text 15693 group 2; posarea: Colossus of Zora -7340,1643 in 2743'),
(137710, 2, 5, 255, 'Outside the hive Captain Blackanvil''s Ironforge Brigade now keeps watch for the Cenarion Circle, which expects something major here, and Alliance volunteers report to him for field duty. Sergeant Carnes grumbles that his reward for gathering war supplies was a post beside a bug hive with a band of sweaty dwarves. Nearby, Marshal Bluewall commands an Alliance camp racing the Horde for silithyst.', 'mod-individual-progression ipp_aware_npcs.sql: Orgrimmar Legion and Ironforge Brigade posts phaseMask IPPPHASE_II (IndividualProgression.cpp checkIPPhasing: Silithus and the hives from state 5); npc_text 7874 (Janela), 8212 (Carnes); quests 8507, 9415, 9419'),
(137711, 1, 0, 255, 'Somewhere in its depths is Mistress Natalia Mar''alith. The dwarves of the Bronzebeard camp saw her run into this hive after her madness took her, and not one insect tried to bar her way.', 'npc_text 7767 (Frankal); quest 8306 description'),
(137711, 2, 4, 4, 'The war has reached the hive. The Colossus of Regal has risen to serve its master, and before the hive a great resonating crystal of the qiraji has broken through the sand, with supreme anubisath warbringers standing guard over it.', 'mod-individual-progression aq_war.sql: colossi, Nokhor, supreme warbringers and resonating crystals in IPPPHASE (state 4 only in 1377, 2737, 2741 and the hives); aq_war.sql creature_text 15693 group 4; posarea: Colossus of Regal -7824,663 and crystal 180810 -7831,857 in 2744'),
(137711, 3, 5, 255, 'Outside its mouth the Orgrimmar Legion now stands for the Cenarion Circle under Captain Krug Skullsplit, proud to serve Thrall however far from home, who signs the field papers of Horde volunteers in silithid blood. Close by, General Kirika''s Horde camp gathers silithyst, determined to keep it from the Alliance.', 'mod-individual-progression ipp_aware_npcs.sql: Orgrimmar Legion and Ironforge Brigade posts phaseMask IPPPHASE_II (IndividualProgression.cpp checkIPPhasing: Silithus and the hives from state 5); npc_text 8059 (Krug); quests 8731 reward text, 9416, 9422'),
(137712, 1, 0, 255, 'Brann has left word after all. A letter in his hand, turned up among the silithid of the hives, tells of a great battle between a Titan and an Old God, a bona fide one, he stressed, and of an ancient tunnel leading into Ahn''Qiraj, which he meant to take. Most of his crew, he wrote, was already dead, and he asked that his monkey be fed and hugged.', 'quest 8308 description (item-started, item 20461); quest 8308 reward text'),
(137714, 1, 0, 255, 'Those who gaze into the tear feel a sorrow so heavy they fear they might die of it, and as it passes, something stirs in the depths of the crystal: a memory of the old war, long forgotten.', 'quest 8305 reward text; quest 8519 description'),
(137715, 1, 0, 3, 'The gates remain shut. Great roots and glowing runes of warding bind them fast, as they have since the day they were sealed, and whatever stirs in the city behind them stays behind them.', 'mod-individual-progression aq_gate_quest.sql: Gate of Ahn''Qiraj, Gate Roots, Gate Runes (176146-176148) state 1, aq_gate CanBeSeen before state 5'),
(137715, 2, 0, 255, 'The vision in the crystalline tear told why a sacred gong was set before the gates. Anachronos once told Fandral Staghelm that the Scepter of the Shifting Sands, used upon that gong, would dissolve the magic holding the barrier together and loose the horrors of Ahn''Qiraj on the world once more.', 'creature_text 15381 group 7 (Anachronos the Ancient, vision event of 8519; spoken by the core script and by mod-individual-progression''s replacement, same groups)'),
(137715, 3, 0, 255, 'The gong was given a keeper. Jonathan the Revelator, an eternal watcher of the bronze flight, was posted upon the dais, empowered by the Timeless One himself to grant the champion of the gong a gift from Nozdormu''s timeless treasure trove.', 'quest 8745 reward text; ipp_aware_npcs.sql: 15693 npc_ipp_aqwewar (states 3-4)'),
(137715, 4, 4, 4, 'The gong has been rung. At its sound the roots, the runes and the great doors gave way one after another, and the qiraji came out to meet the world: colossal anubisath warbringers and an Imperial Qiraji Destroyer now stand guard before the wall.', 'mod-individual-progression aq_war.sql: colossi, Nokhor, supreme warbringers and resonating crystals in IPPPHASE (state 4 only in 1377, 2737, 2741 and the hives); aq_war.sql 15743, 15744 at -7953,1588 to -8107,1536 (2737 and 1377); aq_scripts.cpp gobject_scarab_gong: roots, runes and door open in turn, reset after five minutes'),
(137715, 5, 5, 255, 'Now nothing bars the way through the Scarab Wall. Its gates stand open, and the Circle''s allies carry the war through them into the ruined city and on toward the temple beyond.', 'npc_text 8214, 8216; DB: gate doors 180898, 180899, 180904 spawn state 0 (open); aq_gate_quest.sql: module gate hidden from state 5'),
(137716, 1, 0, 255, 'Natalia was found at last, deep in Hive''Regal, but she had become the High Priestess of C''Thun. The news struck the commander like a blow to the heart. He demanded to know what C''Thun was, and how such a fiend could have turned his sweet Natalia into the monster described to him.', 'quest 8306 reward text; creature_template 15215 subname High Priestess of C''Thun'),
(137716, 2, 5, 255, 'Since the gates opened, his desk has filled with the business of a long war: battle orders captured from the cult''s prophets, and the reports of volunteers sent on field duty against the hives.', 'quest 8498 (field duty briefing); quests 8501, 8502, 8538, 8539, 8770-8777 (turn-ins); mod-individual-progression ipp_aware_npcs.sql: npc_ipp_aq (15498, 15499, 15500, 15540, 16091, seen from state 5)'),
(137717, 1, 0, 255, 'His long watch is over. The great one has risen, and Baristolth, his duty as a Watcher fulfilled, turned at once to the search for a single hero, one who might rise above all others and earn the favor of the Brood.', 'quest 8286 reward text; quest 8288 description and request text'),
(137717, 2, 0, 255, 'In time he owned that he had kept much in secret, for enemies abound, he said, even under their very noses. With an apology he handed over an old tome on the war he had lived through, and sent his chosen on to seek his master.', 'quest 8303 description'),
(137718, 1, 0, 255, 'Her greatest find came from a glyphed prism of the hives. Once unlocked, its layers gave up a record reaching back two hundred centuries, by her reckoning, but the more she read the paler she grew. If what it foretold ever came to pass, she warned, it could mean the end of every future.', 'quest 8315 reward text; quests 8316, 8376-8382 reward text (Armaments of War, one per class, autocomplete, after 8315)'),
(137719, 1, 0, 255, 'In time Huum learned that the cult answers to something darker still: the Abyssal Council, master of the Hammer by way of its wind stones. The brothers'' war on the cult became a war on the Council, and Huum sent the Circle''s heroes to Aurel Goldleaf, whose craft the next gambit would need.', 'quest 8331 description (given by Huum 15270)'),
(137719, 2, 0, 255, 'Bor sends only true armies against a lord of the Council, and he admits he would do anything to leave his post and wrestle one of those things himself. When one was brought down at last he could hardly believe it, and handed over the biggest chest in the hold, filled with the best of what they had found.', 'quest 8352 description, request and reward text'),
(137720, 1, 0, 255, 'Yet an enemy of the cult is a friend of his. The Twilight''s Hammer hunts him like a beast to this day, and he knows the code its scribes use and the book that unlocks it, the Twilight Lexicon, whose three chapters the cult keeps apart.', 'quest 8285 reward text; quest 8279 description'),
(137720, 2, 0, 255, 'With the Lexicon in his hands he reads the cult''s secret monthly bulletin, the True Believer, watching for word that the search for him has made progress or been called off. Whatever else of use he learns from it, he is willing to pass on.', 'quest 8323 description and reward text'),
(137721, 1, 0, 255, 'Those who freed the prince learned what Demitrian''s master truly was. Thunderaan rose from his bonds as an enemy and had to be cut down, and his victors came back to force the lying wretch to wake the blade made from his betrayal. Demitrian only cowered before them and begged to be left to reshape his pathetic life.', 'quest 7786 reward text; quest 7787 description, request and reward text'),
(137722, 1, 5, 255, 'Now that the war has moved inside the gates, the scouts the Circle keeps hidden in the three hives send their written reports to her as well, and she reads each one the moment it arrives.', 'quests 8534, 8738, 8739 (scout reports, field duty briefings); mod-individual-progression ipp_aware_npcs.sql: npc_ipp_aq (15498, 15499, 15500, 15540, 16091, seen from state 5)'),
(137723, 1, 0, 255, 'Restored, the tablet held words she could read but no meaning, for the cult''s sects are known to hide their writings in code. It needed someone who knew more of such things, and rumor told of a cultist named Ortell who had deserted his sect and lived as a hermit in the mountains south of Southwind Village.', 'quest 8284 reward text; quest 8285 description'),
(137723, 2, 0, 255, 'Found, Ortell was suspicious, then eager, since anyone who fought the cult was a friend of his. To break the code he needed the Twilight Lexicon, the book the cult''s scribes use, whose three chapters it keeps apart in the hands of its Twilight Keepers at different camps.', 'quest 8285 request and reward text; quest 8279 description; creature_loot_template: Lexicon chapters from Twilight Keepers Mayna, Exeter, Havunth'),
(137723, 3, 0, 255, 'With all three chapters gathered he set to work at once, swapping every third word with one from the second chapter and every other word with one from the first, then stopping to wonder aloud whether he had it backwards.', 'quest 8279 reward text'),
(137723, 4, 0, 255, 'What came out, he declared, was a valuable chunk of information: a cultist''s diary of pilgrims come to Silithus to raise a wind stone through which to commune with their masters. Having watched the Circle''s forces arrive to drive the cult out, he sent the decoded parchment to Commander Mar''alith, hoping it would soon put him beyond the cult''s grasp for good.', 'quest 8287 description; item 20405 Decoded Tablet Transcription (8287 StartItem), page_text 2807-2809'),
(137723, 5, 0, 255, 'Commander Mar''alith found the parchment very interesting indeed. It shed new light on the cult''s presence in Silithus, he said, and would surely help the Circle in its struggle against the Twilight''s Hammer, and he rewarded its bearer handsomely.', 'quest 8287 reward text'),
(137724, 1, 0, 255, 'Rutgar Glyphshaper told how she had been the first from the hold to join their forays into the hives, until in Hive''Regal she pressed her cheek to a glyphed crystal and fell into a trance. The druids woke her, but weeks later she came back demanding they return. Frankal Stonebridge told the rest: she chanted to someone who was not there, then attacked, eyes aglow, flaying their minds, until Glibb drove her off and she fled into the hive. Mar''alith resolved that, alive or dead, she must be found.', 'npc_text 7755-7761 (Rutgar), 7762-7767 (Frankal); quest 8304 reward text'),
(137724, 2, 0, 255, 'Deep in Hive''Regal waited the one she had become, Natalia Mar''alith, High Priestess of C''Thun, crying that C''Thun would retake this world. When word of it reached him, the grieving commander clutched at his chest and could only ask what C''Thun was.', 'quest 8306 description and reward text; creature_template 15215 subname High Priestess of C''Thun; creature_text 15215'),
(137725, 1, 0, 255, 'From the rubbings the dwarves recreated the glyphs on a crystal prism, a means, they found, for the qiraji and other unknown powers to send messages to the silithid. That was all they could learn. The prism would not give up its messages, so they sent it to Geologist Larksbane at Cenarion Hold.', 'quest 8314 description'),
(137725, 2, 0, 255, 'Larksbane saw why. There was nothing to decipher until the prism''s shifting outer layer aligned with the markings within. Its one clue showed an emissary of the qiraji meeting three silithid at the bones of a large dragon, and above it a code she copied as glyphs of calling for the Bones of Grakkarond.', 'quest 8314 reward text; quest 8315 description'),
(137725, 3, 0, 255, 'Drawn in the sand at the bones, the glyphs brought the overlords and then the emissary, and from the emissary came the key to the crystal. Larksbane exclaimed that she held twenty thousand years of history in her hands.', 'quest 8315 reward text'),
(137725, 4, 0, 255, 'What that history foretold shook her. Should the prophecy ever come to pass, she warned, the future of them all could be at an end, and war, with untold horrors, was coming to the desert.', 'quests 8316, 8376-8382 reward text (Armaments of War, autocomplete)'),
(137726, 1, 0, 255, 'The geolords fell, and then Vyral the Vile, slain in the cave of Twilight''s Run, his signet ring carried back to Huum. The druid hailed it as doom for the cult''s operations in Silithus, a blow from which it would not easily recover, though some of them still scurried about.', 'quest 8320 reward text; quest 8321 description and reward text'),
(137726, 2, 0, 255, 'Any hope that the cult''s work in Silithus was slowing proved mistaken. Through the arcane wind stones dotted among its camps, the Hammer answers to an even darker power, the Abyssal Council, and the night elf craftswoman Aurel Goldleaf has devised a gambit to strike at it.', 'quest 8331 description and reward text; quests 9248, 8829 (Aurel''s elven words, prays to Elune); CreatureDisplayInfo 15372 (night elf female)'),
(137726, 3, 0, 255, 'A replica of the cult''s medallion of station, made with a brilliant shard and the crests of slain templars, lets a hero in twilight trappings commune through a wind stone as a mid-ranking cultist and lure a duke of the Council into ambush. Bor rewards every signet brought back.', 'quest 8332 description and reward text; quests 8348, 8363'),
(137726, 4, 0, 255, 'A ring of lordship, worn by the cult''s highest ranks, fools even the lords of the Council through the greater wind stones. Bor warned that such a foe calls for a true army. The lords meet the impostors with fury, swearing that this world will fall to darkness, but one was brought down, and Bor could hardly believe it.', 'quest 8341 description and reward text; quest 8352 description, request and reward text; creature_text 15203-15208, 15220, 15305 (this world will fall to darkness, Imposter)'),
(137727, 1, 0, 255, 'Freeing them proved Layo''s suspicion that the great hive near the village had played a part in its ruin, for each death wail roused the insects, the silithid being keenly sensitive to their surroundings. He asked that the hive be stirred on purpose, from the top of the village tower where the wasps swarm thickest.', 'quest 1125 reward text; quest 1126 description'),
(137727, 2, 0, 255, 'What came out of the hive was a box-shaped thing so encrusted in chitin it could barely be recognized, though one exposed corner hinted at a book beneath. If it was a journal or a log from ancient times, preserved in its shell, it might give the Circle a window into the past.', 'quest 1126 reward text; quest 6844 description'),
(137727, 3, 0, 255, 'Layo sent it to Umber, the Circle''s archivist in Nighthaven, touched, he admits, but brilliant, a man who has saved tomes in far worse shape. If it could be saved, Umber would do it. What he found is a tale for Moonglade.', 'quest 6844 description'),
(137728, 1, 0, 255, 'The master had risen. Baristolth''s watch was ended, and the trials began: only one could rise from the throng of would-be champions to become an ally of the Brood, and the first proof was the head of Broodlord Lashlayer from the lair of the Lord of Blackrock.', 'quest 8286 reward text; quest 8288 description'),
(137728, 2, 0, 255, 'The Brood of Nozdormu distrusts the lesser races, a distrust rooted, Baristolth hinted, in much history best told by the Brood itself. To prove the champion to his master he demanded silithid carapace from the three hives by the hundred, and granted the right to deputize helpers.', 'quest 8301 description, request and reward text; quest 8302'),
(137728, 3, 0, 255, 'His tome, The War of the Shifting Sands, began with Fandral Staghelm and his son. Valstann was ordered to defend Southwind Village and died when it fell. Fandral pushed on in grief, but the qiraji overran Silithus and drove the night elves back to Tanaris, where a humbled Staghelm pleaded with Anachronos. The dragon refused to involve the bronze flight until the qiraji attacked the Caverns of Time.', 'item 20415 The War of the Shifting Sands (8303 StartItem), page_text 2793-2799'),
(137728, 4, 0, 255, 'Even the bronze flight could not stem the tide, so Anachronos called on Merithra of the green, Caelestrasz of the red and Arygos of the blue. Above Ahn''Qiraj they sensed a hidden power shielding its temple, and resolved to raise a barrier from the essence of night elves and dragons, making the city its own prison.', 'page_text 2800-2806'),
(137728, 5, 0, 255, 'Anachronos sent the champion back to Silithus, to a crystalline tear beside the Scarab Wall that stands for the losses of that war. Its sorrow nearly overwhelms those who gaze into it, and within its depths a long forgotten memory stirs.', 'quest 8305 description and reward text; quest 8519 description'),
(137728, 6, 0, 255, 'The memory showed the sealing. Anachronos halted the sands of time and conjured glyphs of warding while Staghelm called forth the roots, and the barrier closed. Then Anachronos offered Staghelm the Scepter of the Shifting Sands, the key that could open it at the gong. Staghelm refused another burden, swore he would have his son back, and hurled the scepter into the barrier, shattering it.', 'creature_text 15381, 15382 (vision event of 8519: Anachronos the Ancient, Fandral Staghelm); creature_text 15378-15380 (Merithra, Caelestrasz, Arygos)'),
(137728, 7, 0, 255, 'After Staghelm''s betrayal Anachronos gathered the pieces and divided them among the flights of the four mighty Aspects, thinking a scepter so divided could never be restored by those seeking chaos. He calls himself a fool for it, for even now that cursed flight hunts him.', 'quest 8519 reward text'),
(137728, 8, 0, 255, 'The guardians of the shards were Eranikus, Vaelastrasz and Azuregos, watchers of the world, and each had fallen to tragedy, through agents of the Old Gods or betrayal by friends, his own naivety partly to blame. It is this, Anachronos admits, that fuels his distrust of mortals.', 'quest 8555 reward text (autocomplete; mod-individual-progression adds the same words as its description in every state)'),
(137728, 9, 0, 255, 'The blue shard lay beneath the Bay of Storms off Azshara. Narain''s arcanite buoy, cast into the swirling maelstrom there, drew up the monstrous Maws, and from the slain beast came the shard. Anachronos promised he would soon be able to reform the scepter.', 'quest 8729 description and reward text; creature_loot_template: Maws 15571 drops Blue Scepter Shard 21137'),
(137728, 10, 0, 255, 'Anachronos greeted the champion as one long foretold. A thousand years had passed, he said, and just as fated, one now stood before him who would lead their people into a new age. The Old God trembles, he warned, for it fears that faith and knows the might of Kalimdor comes with the champion. Shatter the prophecy of C''Thun, he urged, and when the champion was ready he would grant the Scepter of the Shifting Sands.', 'quest 8742 request and reward text (autocomplete; needs 8729, 8730 and 8741, NextQuestID 8742, ExclusiveGroup -8729)'),
(137728, 11, 0, 255, 'The champion struck the Scarab Gong, and the ancient gates of Ahn''Qiraj opened, revealing the horrors of a forgotten war. From the ground beside the gong sprang a crystal, a token, perhaps, of the Brood''s favor.', 'quest 8743 request and reward text; creature_text 15693 group 0 / acore_string 41100 (gong announcement)');
